def quad(m: list[list[int]], u: list[int]) -> int:
    """The quadratic form u.m.u in plain integers."""
    return sum(u[i] * m[i][j] * u[j] for i in range(len(u)) for j in range(len(u)))


def applied(m: list[list[int]], u: list[int]) -> list[int]:
    """m u in plain integers."""
    return [sum(m[i][j] * u[j] for j in range(len(u))) for i in range(len(u))]


